#!/usr/bin/env bash
# Create .env with fresh random secrets. Refuses to overwrite an existing file.
set -euo pipefail
cd "$(dirname "$0")/.."
[[ -e .env ]] && { echo ".env already exists; not overwriting" >&2; exit 1; }

rand() { openssl rand -base64 48 | tr -d '/+=\n' | cut -c1-"${1:-40}"; }
fernet() { openssl rand -base64 32 | tr '+/' '-_'; }
host_ip=$(hostname -I 2>/dev/null | awk '{print $1}')
port=${RAGDAG_HTTPS_PORT:-8443}
public_url=${RAGDAG_PUBLIC_URL:-https://${host_ip:-localhost}:${port}}

umask 077
cat > .env <<ENV
# Generated by scripts/init-env.sh on $(date -u +%FT%TZ). Keep this file secret and backed up:
# losing RAGDAG_VAULT_KEYS makes stored API keys unreadable.
RAGDAG_PUBLIC_URL=${public_url}
RAGDAG_HTTPS_PORT=${port}
RAGDAG_HTTP_PORT=8088
RAGDAG_ALLOW_SIGNUP=false
RAGDAG_MAX_UPLOAD_MB=50
RAGDAG_CLAUDE_MODEL=claude-opus-5-5

RAGDAG_SECRET_KEY=$(rand 64)
# Comma-separated Fernet keys; the first encrypts. Prepend a new key to rotate.
RAGDAG_VAULT_KEYS=$(fernet)

POSTGRES_PASSWORD=$(rand 32)
AIRFLOW_DB_PASSWORD=$(rand 32)
AIRFLOW_FERNET_KEY=$(fernet)
AIRFLOW_JWT_SECRET=$(rand 64)
AIRFLOW_ADMIN_PASSWORD=$(rand 20)
AIRFLOW_SERVICE_PASSWORD=$(rand 32)

# Host folder mounted read-only at /data/sources for folder sources.
RAGDAG_SOURCES_DIR=./data/sources
RAGDAG_BACKUP_DIR=./backups
BACKUP_KEEP_DAYS=14
ENV
mkdir -p data/sources backups && chmod 755 data data/sources  # read by container uid 50000
echo "wrote .env (public URL ${public_url}); Airflow admin password is in AIRFLOW_ADMIN_PASSWORD"
